#!/usr/bin/env python3
"""Regenerate skills/homelab-manager/assets/template-history.json from the release tags.

    python3 .github/template_history.py [--check]

For every file of the repo template it records the git blob hash of each released version, with the
first and last release that shipped it, plus the working tree under plugin.json's version.
init_repo.py --sync-managed uses it to tell a file the user never edited (it matches a released
template) from one with local edits, and replaces only the former (GitHub issue #68).
Run it before tagging a release that changes the template; --check exits 1 when the file is stale.
"""
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PREFIX = "skills/homelab-manager/assets/repo-template/"
OUT = ROOT / "skills/homelab-manager/assets/template-history.json"
DOC = ["Generated by .github/template_history.py: never edit by hand.",
       "files: template path -> {git blob hash: [first release, last release] that shipped that content}."]


def vtuple(v):
    return tuple(int(x) for x in re.fullmatch(r"v?(\d+)\.(\d+)\.(\d+)", v).groups())


def blob_hash(data: bytes) -> str:
    return hashlib.sha1(b"blob %d\0" % len(data) + data).hexdigest()


def git(*args) -> str:
    return subprocess.run(["git", *args], cwd=ROOT, capture_output=True, text=True, check=True).stdout


def snapshots():
    """[(version, {rel: blob hash})] oldest first, the working tree last."""
    tags = sorted((t for t in git("tag", "--list", "v*").split() if re.fullmatch(r"v\d+\.\d+\.\d+", t)), key=vtuple)
    out = []
    for t in tags:
        files = {}
        for line in git("ls-tree", "-r", t, "--", PREFIX).splitlines():
            meta, path = line.split("\t", 1)
            if path.endswith(".DS_Store"):
                continue
            files[path[len(PREFIX):]] = meta.split()[2]
        if files:
            out.append((t[1:], files))
    have = json.loads((ROOT / ".claude-plugin/plugin.json").read_text())["version"]
    tree = ROOT / PREFIX
    out.append((have, {p.relative_to(tree).as_posix(): blob_hash(p.read_bytes())
                       for p in sorted(tree.rglob("*")) if p.is_file() and p.name != ".DS_Store"}))
    return out


def build() -> dict:
    files: dict = {}
    for version, snap in snapshots():
        for rel, h in snap.items():
            span = files.setdefault(rel, {}).setdefault(h, [version, version])
            if vtuple(version) < vtuple(span[0]):
                span[0] = version
            if vtuple(version) > vtuple(span[1]):
                span[1] = version
    return {"_doc": DOC, "files": {k: files[k] for k in sorted(files)}}


def main(argv) -> int:
    text = json.dumps(build(), indent=1) + "\n"
    if "--check" in argv:
        if not OUT.exists() or OUT.read_text() != text:
            print(f"{OUT.relative_to(ROOT)} is stale: run python3 .github/template_history.py", file=sys.stderr)
            return 1
        return 0
    OUT.write_text(text)
    print(f"Wrote {OUT.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
